INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('HN006', 53, '{"id":"HN006","name":"Cột cờ Hà Nội","area":"Ba Đình","lat":21.0319,"lng":105.8397,"type":"attraction","moods":["nostalgia","energy"],"groups":["solo","couple","friends","family"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":25,"cost":20000,"desc":"Kỳ đài 1805 cao 60 m — biểu tượng thủ đô, leo lên nhìn mái ngói khu Ba Đình.","badges":["Lịch sử","Ngoài trời"],"tip":"28A Điện Biên Phủ, cạnh Bảo tàng Lịch sử Quân sự. Giờ mở cửa các nguồn khác nhau, nên đến trước 16h."}', 1794147965656);
