INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('MU01', 55, '{"id":"MU01","name":"Bảo tàng Lịch sử Quốc gia","area":"Hoàn Kiếm","lat":21.0245,"lng":105.86,"type":"museum","moods":["nostalgia","calm"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":75,"cost":40000,"desc":"Hiện vật từ thời tiền sử đến triều Nguyễn trong toà nhà kiến trúc Đông Dương cạnh Nhà hát Lớn.","badges":["Trong nhà","Lịch sử"],"tip":"1 Tràng Tiền. Nghỉ thứ Hai; hiện có hai cơ sở (Tràng Tiền và Trần Quang Khải)."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('MU02', 56, '{"id":"MU02","name":"Bảo tàng Mỹ thuật Việt Nam","area":"Ba Đình","lat":21.0305,"lng":105.8362,"type":"museum","moods":["calm","nostalgia"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":60,"cost":40000,"desc":"Tranh sơn mài, tượng Phật và điêu khắc dân gian trong toà nhà kiểu Pháp yên tĩnh.","badges":["Trong nhà","Nghệ thuật"],"tip":"66 Nguyễn Thái Học, gần Văn Miếu."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('HT006', 57, '{"id":"HT006","name":"Phủ Tây Hồ","area":"Tây Hồ","lat":21.0557,"lng":105.8196,"type":"attraction","moods":["calm","nostalgia"],"groups":["solo","couple","friends","family"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":30,"cost":0,"desc":"Phủ thờ Mẫu linh thiêng bên Hồ Tây — không khí hương khói, nhiều người đến lễ ngày rằm.","badges":["Tâm linh","Ngoài trời"],"tip":"52 Đặng Thai Mai. Ăn mặc kín đáo, giữ yên tĩnh."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('TD005', 58, '{"id":"TD005","name":"Phố Tây Tạ Hiện","area":"Hoàn Kiếm","lat":21.0346,"lng":105.8524,"type":"attraction","moods":["energy","adventure"],"groups":["friends","solo","couple"],"indoor":false,"timeOfDay":["evening"],"duration":75,"cost":0,"desc":"Con phố bia hơi và quán bar sôi động nhất phố cổ về đêm — người từ khắp nơi ngồi ghế nhựa ngoài vỉa hè.","badges":["Buổi tối","Ngoài trời","Đông vui"],"tip":"Đông nhất từ 20h tối cuối tuần. Giữ kỹ đồ đạc."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM004', 59, '{"id":"AM004","name":"Bún thang Bà Đức","area":"Hoàn Kiếm","lat":21.0322,"lng":105.8531,"type":"food","moods":["nostalgia","calm"],"groups":["solo","couple","friends","family"],"indoor":false,"timeOfDay":["morning","afternoon"],"duration":30,"cost":43000,"desc":"Bát bún thang cầu kỳ với trứng, giò, gà xé — nước dùng trong, thanh, một món ăn của người Hà Nội xưa.","badges":["TB ~43.000đ (menu chưa đủ)","Ẩm thực HN","Ngoài trời"],"tip":"48 Cầu Gỗ. Trang Foody ghi nhận ít hoạt động gần đây — nên kiểm tra quán còn mở.","priceQuality":"partial","menu":[{"n":"Bún thang (bát)","p":35000},{"n":"Bún thang (bát, khách khác)","p":50000}],"menuSrc":["https://www.foody.vn/ha-noi/bun-thang-ba-duc-48-cau-go","https://mia.vn/cam-nang-du-lich/bun-thang-cau-go-ha-noi-13970"],"menuChecked":"2026-10","menuNote":"Giá từ đánh giá khách 2019; mia.vn 12/2023 ghi 30-55k/người. Chưa có menu chính thức."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM005', 60, '{"id":"AM005","name":"Bánh tôm Bánh gối Hàng Bồ","area":"Hoàn Kiếm","lat":21.0339,"lng":105.8491,"type":"food","moods":["adventure","nostalgia"],"groups":["solo","friends","couple"],"indoor":false,"timeOfDay":["afternoon"],"duration":25,"cost":16000,"desc":"Bánh gối, bánh tôm, há cảo chiên giòn ăn nóng với nước chấm chua ngọt — món quà vặt chiều phố cổ.","badges":["TB ~16.000đ (menu chưa đủ)","Ăn vặt","Chiều"],"tip":"57A Hàng Bồ, chỉ mở khoảng 15h-18h.","priceQuality":"partial","menu":[{"n":"Bánh gối (cái)","p":10000},{"n":"Bánh tôm (cái)","p":8000},{"n":"Há cảo (đĩa)","p":30000}],"menuSrc":["https://foody.vn/ha-noi/banh-tom-hang-bo"],"menuChecked":"2026-10","menuNote":"Giá từ đánh giá khách 2019-2020, tính theo cái/đĩa nên không phải chi tiêu mỗi người."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM006', 61, '{"id":"AM006","name":"Cháo sườn cô Là","area":"Hoàn Kiếm","lat":21.031,"lng":105.8486,"type":"food","moods":["calm","nostalgia"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":25,"cost":32000,"desc":"Cháo sườn sụn ninh nhừ, ăn kèm quẩy và ruốc — bữa sáng ấm bụng ngày se lạnh.","badges":["TB ~32.000đ (menu chưa đủ)","Sáng sớm","Trong nhà"],"tip":"2A Lý Quốc Sư, mở sáng và chiều tối.","priceQuality":"partial","menu":[{"n":"Cháo sườn quẩy ruốc (phần)","p":30000},{"n":"Cháo sườn (bát)","p":25000},{"n":"Cháo sườn quẩy ruốc (bát)","p":40000}],"menuSrc":["https://foody.vn/ha-noi/chao-suon-co-la-ly-quoc-su"],"menuChecked":"2026-10","menuNote":"Giá từ đánh giá khách 2019-2020 — có thể đã tăng."}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM007', 62, '{"id":"AM007","name":"Quán Ăn Ngon","area":"Hoàn Kiếm","lat":21.0265,"lng":105.8436,"type":"food","moods":["energy","adventure"],"groups":["solo","couple","friends","family"],"indoor":true,"timeOfDay":["morning","afternoon","evening"],"duration":60,"cost":200000,"desc":"Nhà hàng gom nhiều món đường phố ba miền trong một sân vườn — tiện khi muốn thử nhiều món một lần.","badges":["Ước tính ~200.000đ","Nhiều món","Trong nhà"],"tip":"18 Phan Bội Châu. Chi tiêu thường dưới khoảng 250k/người gồm nước.","priceQuality":"est"}', 1794147965656);
INSERT OR REPLACE INTO places (id, sort, json, updated_at) VALUES ('AM008', 63, '{"id":"AM008","name":"Bún nem Vương Phố Cổ","area":"Hoàn Kiếm","lat":21.0356,"lng":105.8531,"type":"food","moods":["energy","adventure"],"groups":["solo","friends","couple"],"indoor":true,"timeOfDay":["morning","afternoon"],"duration":30,"cost":38000,"desc":"Bún trộn, bún chả và nem cua bể ở quán nhỏ trong phố cổ, phục vụ nhanh bữa trưa.","badges":["TB ~38.000đ (menu chưa đủ)","Bữa trưa","Trong nhà"],"tip":"37 Đào Duy Từ, mở khoảng 9h-14h.","priceQuality":"partial","menu":[{"n":"Bún trộn (bát)","p":35000},{"n":"Bún chả (phần)","p":40000}],"menuSrc":["https://foody.vn/ha-noi/bun-nem-vuong-pho-co"],"menuChecked":"2026-10","menuNote":"Giá từ đánh giá khách 2019 và 2023."}', 1794147965656);
